BEGIN /* snapshot-journal-owner:c4e903f1-fdd4-4eba-8189-3305defcbf2c */ DECLARE journalCeiling BIGINT UNSIGNED;
DECLARE journalRevision BIGINT UNSIGNED;
DECLARE journalEnabled BOOLEAN; IF TRUE THEN SELECT ceiling INTO journalCeiling FROM snapshot_journal_clock WHERE id=1 FOR SHARE;
SELECT NOT EXISTS(SELECT 1 FROM snapshot_journal_invalid WHERE id=1) INTO journalEnabled;
IF journalEnabled THEN
  INSERT INTO snapshot_journal_events() VALUES();
  SET journalRevision=LAST_INSERT_ID();
  DELETE FROM snapshot_journal_events WHERE revision=journalRevision;
  IF journalRevision>journalCeiling THEN
    INSERT IGNORE INTO snapshot_journal_invalid(id,reason) VALUES(1,IF(journalRevision>9223372036854775807,'revision-exhausted','capacity-exhausted'));
    SET journalEnabled=FALSE;
  END IF;
END IF; IF NOT COALESCE(((NEW.snapshotRowId BETWEEN 1 AND 9007199254740991) AND (0 BETWEEN 0 AND 9007199254740991) AND (OCTET_LENGTH(CAST('' AS BINARY))<=400) AND (NEW.snapshotUserId BETWEEN 1 AND 9007199254740991)),FALSE) THEN INSERT IGNORE INTO snapshot_journal_invalid(id,reason) VALUES(1,'key-out-of-range'); SET journalEnabled=FALSE; END IF; IF journalEnabled THEN INSERT INTO snapshot_journal_scope(tableId,userId,id1,id2,exactText,revision,present) SELECT NEW.snapshotTableId,NEW.snapshotUserId,NEW.snapshotRowId,0,CAST('' AS BINARY),journalRevision,1 ON DUPLICATE KEY UPDATE revision=VALUES(revision),present=VALUES(present);  END IF; END IF; END

